using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

[McpServerToolType]
public class WeatherTools
{
    /// <summary>
    /// MCP tools receive DI services via method parameters.
    /// The SDK inspects each parameter:
    ///   - Known service types (IHttpClientFactory, CancellationToken, etc.)
    ///     are resolved from the DI container automatically.
    ///   - All other parameters become tool input arguments exposed to the LLM.
    /// No constructor injection needed — the class can be static or instance.
    /// </summary>

    [McpServerTool(Name = "get_weather"), Description("Get current weather for a location.")]
    public static async Task<string> GetWeather(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current_weather=true";

        var response = await client.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);
        var weather = response?.CurrentWeather;

        if (weather is null)
            return "No weather data available.";

        return $"Temperature: {weather.Temperature}°C, "
             + $"Wind: {weather.WindSpeed} km/h, "
             + $"Direction: {weather.WindDirection}°, "
             + $"Code: {weather.WeatherCode}";
    }

    [McpServerTool(Name = "get_forecast_summary"), Description("Check if temperature exceeds a threshold at a location.")]
    public static async Task<string> GetForecastSummary(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude")] double latitude,
        [Description("Longitude")] double longitude,
        [Description("Temperature threshold in °C")] double threshold,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current_weather=true";

        var response = await client.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);
        var temp = response?.CurrentWeather?.Temperature;

        if (temp is null)
            return "Unable to retrieve temperature.";

        return temp >= threshold
            ? $"Yes — current temperature {temp}°C meets or exceeds {threshold}°C."
            : $"No — current temperature {temp}°C is below {threshold}°C.";
    }
}

public record WeatherResponse
{
    [JsonPropertyName("current_weather")]
    public CurrentWeather? CurrentWeather { get; init; }
}

public record CurrentWeather
{
    [JsonPropertyName("temperature")]
    public double Temperature { get; init; }

    [JsonPropertyName("windspeed")]
    public double WindSpeed { get; init; }

    [JsonPropertyName("winddirection")]
    public double WindDirection { get; init; }

    [JsonPropertyName("weathercode")]
    public int WeatherCode { get; init; }
}
CSHARP
